import uuid
from collections import defaultdict

from dateutil.relativedelta import relativedelta
from django.db import migrations, models

PASSOS = {'mensal': 'months', 'semanal': 'weeks', 'anual': 'years'}
LIMITE_OCORRENCIAS = 1000


def montar_series(apps, schema_editor):
    """Agrupa despesas fixas por descrição + periodicidade. Dentro do grupo, a mais antiga é a âncora e as
    seguintes entram na mesma série só se o vencimento cair exatamente numa ocorrência prevista; as demais
    viram séries próprias."""
    Despesa = apps.get_model('core', 'Despesa')
    grupos = defaultdict(list)
    for d in Despesa.objects.filter(is_fixed=True).exclude(recurrence_period__isnull=True).order_by('data_vencimento', 'id'):
        if d.recurrence_period in PASSOS:
            grupos[(d.descricao.strip().lower(), d.recurrence_period)].append(d)

    series = 0
    for (descricao, periodo), despesas in grupos.items():
        passo = PASSOS[periodo]
        abertas = []  # (serie_id, ancora, numeros_usados)
        for d in despesas:
            alocada = False
            for serie_id, ancora, usados in abertas:
                numero = next(
                    (n for n in range(1, LIMITE_OCORRENCIAS) if ancora + relativedelta(**{passo: n}) == d.data_vencimento),
                    None,
                )
                if numero is not None and numero not in usados:
                    d.serie_id, d.data_ancora, d.numero_ocorrencia = serie_id, ancora, numero
                    usados.add(numero)
                    alocada = True
                    break
            if not alocada:
                serie_id = uuid.uuid4()
                abertas.append((serie_id, d.data_vencimento, {0}))
                d.serie_id, d.data_ancora, d.numero_ocorrencia = serie_id, d.data_vencimento, 0
                series += 1
            d.save(update_fields=['serie_id', 'data_ancora', 'numero_ocorrencia'])
    total = sum(len(v) for v in grupos.values())
    if total:
        print(f'\n  {total} despesa(s) fixa(s) organizadas em {series} série(s).')


